-- Original ExamHabitat practice material, authored for this project. Not official CAT questions.
-- IDs are stable; repeat seed application never duplicates or overwrites published versions.
insert into public.practice_sets(id,kind,title,body,columns,rows) values
('cat-reading-gardens-v1','passage','Gardens and evidence',
'A city offered small grants to neighbourhood groups that maintained public gardens. After a year, streets with gardens had more pedestrian visits than streets without them. Officials called this proof that the grants had revived street life. Yet groups had applied voluntarily: neighbourhoods with active residents may have been more likely both to seek grants and to attract visitors. The gardens might still have helped, but the comparison alone cannot establish how much. A better evaluation would compare changes over time in otherwise similar streets, including some that wanted a garden but had to wait for a grant. Such evidence need not delay every promising project; it can help the city decide which projects deserve expansion.','[]','[]'),
('cat-data-libraries-v1','case','Library lending',
'The table gives the number of books lent by three libraries in two years. All counts are exact. Use only the data shown.',
'["Library","2024","2025"]','[["North","40","60"],["East","50","75"],["West","80","100"]]'),
('cat-logic-talks-v1','case','Four talks',
'Four speakers A, B, C and D each give one talk in four consecutive slots numbered 1 to 4. B speaks before A. D speaks immediately after A. C does not speak first. There are no other constraints.','[]','[]')
on conflict(id) do nothing;

with content(id,topic_id,section,difficulty,type,prompt,choices,answer_key,explanation,set_id,set_position) as (values
('cat-p-001','cat-varc-rc-main-idea','VARC',2,'mcq','Which statement best captures the central argument of the passage?',
'["Garden grants should be stopped until perfect evidence exists.","Higher visits alone do not prove the grants caused the change; better comparisons can guide expansion.","Voluntary groups cannot maintain public gardens effectively.","Only streets without gardens can reveal changes in street life."]'::jsonb,'B',
'The passage questions a causal claim based on a simple comparison, proposes a better evaluation and explicitly allows promising projects to continue. It neither rejects gardens nor demands perfect evidence.','cat-reading-gardens-v1',1),
('cat-p-002','cat-varc-rc-inference','VARC',2,'mcq','Why does voluntary application matter to the evaluation?',
'["It guarantees that all neighbourhoods had identical starting conditions.","It proves that gardens had no effect on visits.","Applicants may already have characteristics that also attract visitors.","It means grant amounts were randomly assigned."]'::jsonb,'C',
'Active residents may be more likely to apply and independently attract visitors. This selection effect can confound the garden-versus-no-garden comparison; it does not prove a zero garden effect.','cat-reading-gardens-v1',2),
('cat-p-003','cat-varc-rc-tone','VARC',1,'mcq','The attitude of the author toward the garden programme is best described as:',
'["Cautiously supportive of evaluation and possible expansion.","Unconditionally celebratory.","Hostile to all public spending.","Indifferent to the quality of evidence."]'::jsonb,'A',
'The author allows that gardens may help and says evaluation need not delay every promising project, while requesting stronger evidence before expansion. This is cautious rather than hostile or unconditional support.','cat-reading-gardens-v1',3),
('cat-p-004','cat-varc-rc-structure','VARC',3,'mcq','What role do streets waiting for a grant play in the proposed evaluation?',
'["They are guaranteed to have no active residents.","They replace the need to measure visits over time.","They prove that gardens are the only cause of visits.","They may provide a comparison group with a similar desire for a garden."]'::jsonb,'D',
'Waiting streets also wanted gardens, so comparing their changes with funded streets can reduce the selection problem. The passage calls for otherwise similar streets and changes over time, not a guaranteed causal proof from waiting alone.','cat-reading-gardens-v1',4),
('cat-p-005','cat-varc-va-summary','VARC',2,'mcq','Choose the best summary: A faster train may save ten minutes between stations, yet travellers may gain little if infrequent connecting buses add long waits. Improving a journey therefore requires attention to transfers as well as speed.',
'["Train speed is irrelevant to every journey.","Buses should always replace trains.","Whole-journey improvements depend on connections as well as the speed of individual services.","Ten minutes is the maximum possible saving from public transport."]'::jsonb,'C',
'The paragraph contrasts a faster segment with waiting at transfers and argues for whole-journey planning. It does not say speed is irrelevant or propose replacing trains.',null,null),
('cat-p-006','cat-varc-va-summary','VARC',1,'mcq','Choose the best summary: A museum digitised its collection, making distant objects easy to inspect. But a high-resolution image cannot convey the scale and texture of every artefact. Digital access expands the encounter rather than replacing all physical visits.',
'["Digital collections broaden access but do not reproduce every feature of a physical encounter.","Digitisation makes every museum visit unnecessary.","Only distant visitors benefit from museums.","Images never convey any useful information."]'::jsonb,'A',
'The paragraph recognises improved access while specifying limits such as scale and texture. The correct option retains both claims without turning a limitation into a total rejection.',null,null),
('cat-p-007','cat-varc-va-odd-sentence','VARC',2,'numeric','Enter the number of the sentence that does not fit the paragraph. (1) Seeds stored in dry conditions can remain dormant. (2) Water activates processes that begin germination. (3) A compass needle usually points toward magnetic north. (4) The emerging root then helps the seedling absorb more water.',
'[]'::jsonb,'3','Sentences 1, 2 and 4 form a sequence about dormancy, germination and root growth. Sentence 3 concerns magnetism and breaks that biological thread.',null,null),
('cat-p-008','cat-varc-va-jumbles','VARC',2,'mcq','Choose the most coherent order. A: This reduced the time spent searching for them. B: The workshop had kept its tools in unlabelled boxes. C: The team could then finish repairs earlier. D: It replaced those boxes with labelled racks.',
'["B-D-A-C","A-C-B-D","D-B-C-A","C-A-D-B"]'::jsonb,'A','B introduces the old storage problem. D changes that system; those boxes refers to B. A gives the immediate consequence of labelled racks, and C gives the downstream effect on repairs.',null,null),
('cat-p-009','cat-dilr-di-tables','DILR',1,'mcq','Which library had the largest absolute increase in lending from 2024 to 2025?',
'["North","East","West","All three were equal"]'::jsonb,'B','The increases are North: 60 - 40 = 20, East: 75 - 50 = 25, and West: 100 - 80 = 20. East has the largest absolute increase.','cat-data-libraries-v1',1),
('cat-p-010','cat-dilr-di-tables','DILR',1,'numeric','How many books did the three libraries lend in total in 2025?',
'[]'::jsonb,'235','Add the three entries for 2025: 60 + 75 + 100 = 235 books. This is a total count, not a percentage change.','cat-data-libraries-v1',2),
('cat-p-011','cat-dilr-di-tables','DILR',2,'mcq','Which libraries had a 50% increase in lending from 2024 to 2025?',
'["North only","West only","North and East only","East and West only"]'::jsonb,'C','North increased by 20 on a base of 40, or 50%. East increased by 25 on 50, also 50%. West increased by 20 on 80, or 25%.','cat-data-libraries-v1',3),
('cat-p-012','cat-dilr-di-tables','DILR',2,'numeric','If each library lends 20% more books in 2026 than in 2025, what will be the total lending in 2026?',
'[]'::jsonb,'282','The 2025 total is 235. A common increase of 20% gives 235 × 1.2 = 282. Equivalently, add 72, 90 and 120.','cat-data-libraries-v1',4),
('cat-p-013','cat-dilr-lr-scheduling','DILR',2,'mcq','Who must speak in slot 1?',
'["A","B","C","D"]'::jsonb,'B','A cannot be first because B precedes A. D cannot be first because it follows A immediately, and C is explicitly not first. Therefore B must be first.','cat-logic-talks-v1',1),
('cat-p-014','cat-dilr-lr-scheduling','DILR',3,'numeric','How many complete schedules satisfy all the conditions?',
'[]'::jsonb,'2','B must be first. The consecutive A-D block can occupy slots 2-3, leaving C fourth, or slots 3-4, leaving C second. The two schedules are B-A-D-C and B-C-A-D.','cat-logic-talks-v1',2),
('cat-p-015','cat-dilr-lr-scheduling','DILR',2,'mcq','If C speaks in slot 4, who speaks in slot 3?',
'["A","B","C","D"]'::jsonb,'D','With B first and C fourth, the consecutive A-D block occupies slots 2 and 3. D therefore speaks in slot 3.','cat-logic-talks-v1',3),
('cat-p-016','cat-dilr-lr-scheduling','DILR',2,'mcq','Which is the complete set of possible slots for A?',
'["1 and 2","2 only","2 and 3","3 and 4"]'::jsonb,'C','In B-A-D-C, A is second; in B-C-A-D, A is third. A cannot be first because B precedes it, or fourth because D must immediately follow.','cat-logic-talks-v1',4),
('cat-p-017','cat-qa-arithmetic-percentages','QA',1,'numeric','A price of 1200 is increased by 20% and then discounted by 25%. What is the final price?',
'[]'::jsonb,'1080','After the increase the price is 1200 × 1.20 = 1440. The discount applies to this new base: 1440 × 0.75 = 1080.',null,null),
('cat-p-018','cat-qa-arithmetic-ratios','QA',1,'mcq','A and B divide 64 tokens in the ratio 3:5. How many tokens does B receive?',
'["24","32","40","48"]'::jsonb,'C','There are 3 + 5 = 8 ratio units. Each is worth 64/8 = 8 tokens. B receives 5 × 8 = 40 tokens.',null,null),
('cat-p-019','cat-qa-arithmetic-averages','QA',1,'numeric','Five numbers have an average of 18. If the number 22 is removed, what is the average of the remaining four?',
'[]'::jsonb,'17','The original total is 5 × 18 = 90. Removing 22 leaves 68, whose average across four numbers is 68/4 = 17.',null,null),
('cat-p-020','cat-qa-arithmetic-tsd','QA',2,'mcq','A traveller covers 120 km at 60 km/h and another 120 km at 40 km/h. What is the average speed for the entire 240 km journey?',
'["45 km/h","48 km/h","50 km/h","52 km/h"]'::jsonb,'B','The two legs take 2 and 3 hours. Average speed is total distance divided by total time: 240/5 = 48 km/h. Equal distances do not justify averaging the speeds.',null,null),
('cat-p-021','cat-qa-arithmetic-time-work','QA',2,'numeric','A can complete a job in 12 days and B in 18 days. Working together at constant rates, how many days do they need? Give an exact decimal.',
'[]'::jsonb,'7.2','Their combined daily rate is 1/12 + 1/18 = 5/36 of the job. The time is its reciprocal, 36/5 = 7.2 days.',null,null),
('cat-p-022','cat-qa-arithmetic-mixtures','QA',2,'numeric','A 20-litre solution contains 30% salt by volume. Ten litres of water are added, with volumes additive. What is the new salt percentage? Enter the percentage number only.',
'[]'::jsonb,'20','The salt volume remains 20 × 0.30 = 6 litres. The final volume is 30 litres, so the percentage is 100 × 6/30 = 20.',null,null),
('cat-p-023','cat-qa-algebra-linear','QA',1,'mcq','If 2x + 3y = 17 and x - y = 1, what is x?',
'["2","3","4","5"]'::jsonb,'C','Substitute x = y + 1 into the first equation: 2y + 2 + 3y = 17, giving y = 3. Thus x = 4.',null,null),
('cat-p-024','cat-qa-algebra-quadratic','QA',2,'numeric','If the roots of x² - 10x + 21 = 0 are a and b, what is a² + b²?',
'[]'::jsonb,'58','The sum of the roots is 10 and their product is 21. Therefore a² + b² = (a+b)² - 2ab = 100 - 42 = 58. The roots 3 and 7 confirm this.',null,null),
('cat-p-025','cat-qa-algebra-inequalities','QA',3,'mcq','How many integers satisfy x² - 5x + 6 < 0?',
'["0","1","2","3"]'::jsonb,'A','Factor the expression as (x-2)(x-3). It is negative only for 2 < x < 3. There are no integers strictly between these bounds; the endpoints give zero and are excluded.',null,null),
('cat-p-026','cat-qa-algebra-sequences','QA',1,'numeric','The arithmetic progression begins 5, 9, 13, 17. What is its 12th term?',
'[]'::jsonb,'49','The common difference is 4. The nth term is 5 + (n-1) × 4, so the 12th term is 5 + 44 = 49.',null,null),
('cat-p-027','cat-qa-geometry-triangles','QA',1,'mcq','A right triangle has perpendicular sides of lengths 6 and 8. What is its area?',
'["14","24","30","48"]'::jsonb,'B','The perpendicular sides can be used as base and height. The area is one half of 6 × 8, which equals 24 square units.',null,null),
('cat-p-028','cat-qa-geometry-circles','QA',1,'numeric','A circle has radius 7 cm. Using π = 22/7, what is its circumference in cm?',
'[]'::jsonb,'44','Circumference equals 2πr. Substituting the specified value gives 2 × (22/7) × 7 = 44 cm. Area would use a different formula.',null,null),
('cat-p-029','cat-qa-number-remainders','QA',3,'mcq','What is the remainder when 7 raised to the power 103 is divided by 5?',
'["1","2","3","4"]'::jsonb,'C','Modulo 5, 7 is equivalent to 2. Powers of 2 repeat remainders 2, 4, 3, 1 with period 4. Since 103 has remainder 3 on division by 4, the required remainder is 3.',null,null),
('cat-p-030','cat-qa-number-hcf-lcm','QA',2,'numeric','Two positive integers have HCF 12 and LCM 180. One integer is 36. What is the other?',
'[]'::jsonb,'60','For two positive integers, their product equals HCF × LCM. The other integer is (12 × 180)/36 = 60. The HCF of 36 and 60 is 12 and their LCM is 180.',null,null),
('cat-p-031','cat-qa-modern-pnc','QA',1,'numeric','How many different two-person committees can be chosen from six people, if the two roles are identical?',
'[]'::jsonb,'15','Identical roles mean order does not matter. There are 6 × 5 ordered choices, but each pair appears twice, giving 30/2 = 15 committees.',null,null),
('cat-p-032','cat-qa-modern-probability','QA',2,'numeric','A bag has three red and two blue balls. Two balls are drawn without replacement. What is the probability that both are red? Give an exact decimal.',
'[]'::jsonb,'0.3','The first ball is red with probability 3/5. Conditional on that event, the second is red with probability 2/4. Their product is 6/20 = 0.3.',null,null)
)
insert into public.practice_questions(id,topic_id,section,difficulty,type,prompt,options,answer_key,explanation,set_id,set_position,published)
select id,topic_id,section,difficulty,type,prompt,
 coalesce((select jsonb_agg(jsonb_build_object('id',chr(64+ordinality::integer),'text',value) order by ordinality) from jsonb_array_elements_text(choices) with ordinality),'[]'),
 answer_key,explanation,set_id,set_position,true from content on conflict(id) do nothing;
